typedef struct { unsigned char *data; size_t size; unsigned status; } HttpResult;
static void set_error(char *e,size_t n,const char *s){if(e&&n)snprintf(e,n,"%s",s);}
static int safe_segment(const char *s){if(!s||!*s)return 0;for(const unsigned char *p=(const unsigned char*)s;*p;p++)if(!isalnum(*p)&&*p!='-'&&*p!='_'&&*p!='.')return 0;return 1;}
static char *json_escape(const char *s){size_t n=strlen(s);if(n>(SIZE_MAX-1)/6)return NULL;char *o=(char*)malloc(n*6+1);if(!o)return NULL;size_t w=0;for(const unsigned char *p=(const unsigned char*)s;*p;p++){if(*p=='"'||*p=='\\'){o[w++]='\\';o[w++]=(char)*p;}else if(*p=='\n'){o[w++]='\\';o[w++]='n';}else if(*p=='\r'){o[w++]='\\';o[w++]='r';}else if(*p=='\t'){o[w++]='\\';o[w++]='t';}else if(*p<0x20){snprintf(o+w,7,"\\u%04x",*p);w+=6;}else o[w++]=(char)*p;}o[w]=0;return o;}
static const char *json_key(const char *json,const char *key){char needle[96];if(snprintf(needle,sizeof(needle),"\"%s\"",key)>=(int)sizeof(needle))return NULL;const char *p=strstr(json,needle);if(!p)return NULL;p+=strlen(needle);while(isspace((unsigned char)*p))p++;if(*p++!=':')return NULL;while(isspace((unsigned char)*p))p++;return p;}
static int json_string_field(const char *json,const char *key,char *out,size_t cap){const char *p=json_key(json,key);if(!p||*p++!='"'||!cap)return 0;size_t n=0;while(*p&&*p!='"'){unsigned char c=(unsigned char)*p++;if(c=='\\'){c=(unsigned char)*p++;if(!c)return 0;switch(c){case 'n':c='\n';break;case 'r':c='\r';break;case 't':c='\t';break;case '"':case '\\':case '/':break;default:return 0;}}if(n+1>=cap)return 0;out[n++]=(char)c;}if(*p!='"')return 0;out[n]=0;return 1;}
static int json_id_field(const char *json,const char *key,char *out,size_t cap){const char *p=json_key(json,key);if(!p||!cap)return 0;size_t n=0;if(*p=='"'){p++;while(*p&&*p!='"'){if(n+1>=cap)return 0;out[n++]=*p++;}if(*p!='"')return 0;}else{while(isalnum((unsigned char)*p)||*p=='-'||*p=='_'){if(n+1>=cap)return 0;out[n++]=*p++;}}if(!n)return 0;out[n]=0;return 1;}

#ifdef _WIN32
static int http_request(const wchar_t *host,unsigned short port,int secure,const wchar_t *verb,const wchar_t *path,const wchar_t *headers,const char *body,size_t body_n,HttpResult *out){
    HINTERNET s=WinHttpOpen(L"AMA-10-C11/0.1",WINHTTP_ACCESS_TYPE_AUTOMATIC_PROXY,WINHTTP_NO_PROXY_NAME,WINHTTP_NO_PROXY_BYPASS,0);if(!s)return 0;WinHttpSetTimeouts(s,10000,10000,30000,30000);HINTERNET c=WinHttpConnect(s,host,port,0);if(!c){WinHttpCloseHandle(s);return 0;}HINTERNET r=WinHttpOpenRequest(c,verb,path,NULL,WINHTTP_NO_REFERER,WINHTTP_DEFAULT_ACCEPT_TYPES,secure?WINHTTP_FLAG_SECURE:0);if(!r){WinHttpCloseHandle(c);WinHttpCloseHandle(s);return 0;}
    BOOL ok=WinHttpSendRequest(r,headers?headers:WINHTTP_NO_ADDITIONAL_HEADERS,headers?(DWORD)-1:0,(LPVOID)body,(DWORD)body_n,(DWORD)body_n,0)&&WinHttpReceiveResponse(r,NULL);DWORD status=0,sz=sizeof(status);if(ok)ok=WinHttpQueryHeaders(r,WINHTTP_QUERY_STATUS_CODE|WINHTTP_QUERY_FLAG_NUMBER,WINHTTP_HEADER_NAME_BY_INDEX,&status,&sz,WINHTTP_NO_HEADER_INDEX)!=0;out->status=status;unsigned char *buf=NULL;size_t used=0,cap=0;while(ok){DWORD available=0;if(!WinHttpQueryDataAvailable(r,&available)){ok=0;break;}if(!available)break;if(available>4*1024*1024-used){ok=0;break;}if(used+available>cap){size_t next=cap?cap*2:4096;while(next<used+available)next*=2;unsigned char *larger=(unsigned char*)realloc(buf,next);if(!larger){ok=0;break;}buf=larger;cap=next;}DWORD got=0;if(!WinHttpReadData(r,buf+used,available,&got)){ok=0;break;}used+=got;}WinHttpCloseHandle(r);WinHttpCloseHandle(c);WinHttpCloseHandle(s);if(!ok){free(buf);return 0;}out->data=buf;out->size=used;return 1;
}
static int parse_origin(const char *url,wchar_t *host,size_t host_cap,unsigned short *port,int *secure){URL_COMPONENTS u;
    int wide_n=MultiByteToWideChar(CP_UTF8,MB_ERR_INVALID_CHARS,url,-1,NULL,0);if(wide_n<=0||wide_n>1024)return 0;wchar_t *wide=(wchar_t*)malloc((size_t)wide_n*sizeof(wchar_t));if(!wide)return 0;if(!MultiByteToWideChar(CP_UTF8,MB_ERR_INVALID_CHARS,url,-1,wide,wide_n)){free(wide);return 0;}memset(&u,0,sizeof(u));u.dwStructSize=sizeof(u);u.dwHostNameLength=(DWORD)-1;u.dwSchemeLength=(DWORD)-1;if(!WinHttpCrackUrl(wide,0,0,&u)){free(wide);return 0;}if(u.dwHostNameLength+1>host_cap){free(wide);return 0;}memcpy(host,u.lpszHostName,u.dwHostNameLength*sizeof(wchar_t));host[u.dwHostNameLength]=0;*secure=u.nScheme==INTERNET_SCHEME_HTTPS;*port=u.nPort;free(wide);return *secure||u.nScheme==INTERNET_SCHEME_HTTP;}
static int to_wide(const char *s,wchar_t **out){int n=MultiByteToWideChar(CP_UTF8,MB_ERR_INVALID_CHARS,s,-1,NULL,0);if(n<=0||n>8192)return 0;*out=(wchar_t*)malloc((size_t)n*sizeof(wchar_t));return *out&&MultiByteToWideChar(CP_UTF8,MB_ERR_INVALID_CHARS,s,-1,*out,n);}
static int call_json(const wchar_t *host,unsigned short port,int secure,const wchar_t *method,const char *path,const char *cookie,const char *body,HttpResult *res){wchar_t *wp=NULL,*wh=NULL;if(!to_wide(path,&wp))return 0;if(cookie){size_t n=strlen(cookie)+128;wh=(wchar_t*)malloc(n*sizeof(wchar_t));if(!wh||swprintf(wh,n,L"Content-Type: application/json\r\nAccept: application/json\r\nCookie: sid=%hs\r\nX-SwanLab-SDK-Version: 0.1.0\r\n",cookie)<0){free(wp);free(wh);return 0;}}else{wh=(wchar_t*)malloc(128*sizeof(wchar_t));if(!wh){free(wp);return 0;}wcscpy(wh,L"Content-Type: application/json\r\nAccept: application/json\r\n");}int ok=http_request(host,port,secure,method,wp,wh,body,body?strlen(body):0,res);free(wp);free(wh);return ok;}
static int check_response(HttpResult *r,char *err,size_t cap,const char *what){if(r->status<200||r->status>=300){char msg[160];snprintf(msg,sizeof(msg),"SwanLab %s failed (HTTP %u)",what,r->status);set_error(err,cap,msg);free(r->data);r->data=NULL;return 0;}if(!r->data){r->data=(unsigned char*)calloc(1,1);if(!r->data)return 0;}else{unsigned char *p=(unsigned char*)realloc(r->data,r->size+1);if(!p)return 0;r->data=p;r->data[r->size]=0;}return 1;}
int ama10_swanlab_upload_csv(const char *base_url,const char *workspace,const char *project,const char *experiment,const char *csv_path,char *error,size_t error_capacity){
    const char *key=getenv("SWANLAB_API_KEY");if(!key||!*key){set_error(error,error_capacity,"SWANLAB_API_KEY is not set");return 0;}if(!base_url||!*base_url)base_url="https://api.swanlab.cn";if(!safe_segment(workspace)||!safe_segment(project)||!experiment||!*experiment||strchr(experiment,'\n')||strchr(experiment,'\r')){set_error(error,error_capacity,"invalid workspace, project, or experiment name");return 0;}
    wchar_t host[512];unsigned short port=0;int secure=0;if(!parse_origin(base_url,host,512,&port,&secure)){set_error(error,error_capacity,"invalid SwanLab API origin");return 0;}char *path=NULL;HttpResult r={0};char sid[512],username[256],project_id[128],experiment_id[128];int ok=0;
    /* SwanLab's current SDK exchanges an API key for a short-lived sid cookie. */
    wchar_t *login_path=NULL;if(!to_wide("/api/login/api_key",&login_path))goto done;size_t hcap=strlen(key)+64;wchar_t *auth=(wchar_t*)malloc(hcap*sizeof(wchar_t));if(!auth){free(login_path);goto done;}if(swprintf(auth,hcap,L"authorization: %hs\r\nAccept: application/json\r\n",key)<0){free(auth);free(login_path);goto done;}if(!http_request(host,port,secure,L"POST",login_path,auth,NULL,0,&r)){free(auth);free(login_path);set_error(error,error_capacity,"SwanLab login HTTPS request failed");goto done;}free(auth);free(login_path);if(!check_response(&r,error,error_capacity,"login"))goto done;if(!json_string_field((char*)r.data,"sid",sid,sizeof(sid))||!json_string_field((char*)r.data,"username",username,sizeof(username))){/* userInfo.username is nested; generic extraction still finds username */set_error(error,error_capacity,"SwanLab login response omitted sid or username");goto done;}free(r.data);r.data=NULL;
    size_t pcap=strlen(workspace)+strlen(project)+64;path=(char*)malloc(pcap);if(!path)goto done;snprintf(path,pcap,"/api/project/%s/%s",workspace,project);if(!call_json(host,port,secure,L"GET",path,sid,NULL,&r)){set_error(error,error_capacity,"SwanLab project request failed");goto done;}if(!check_response(&r,error,error_capacity,"project lookup"))goto done;if(!json_id_field((char*)r.data,"cuid",project_id,sizeof(project_id))&&!json_id_field((char*)r.data,"id",project_id,sizeof(project_id))){set_error(error,error_capacity,"SwanLab project response omitted its ID");goto done;}free(r.data);r.data=NULL;free(path);path=NULL;
    char timestamp[64];SYSTEMTIME st;GetSystemTime(&st);snprintf(timestamp,sizeof(timestamp),"%04u-%02u-%02uT%02u:%02u:%02u.%03uZ",(unsigned)st.wYear,(unsigned)st.wMonth,(unsigned)st.wDay,(unsigned)st.wHour,(unsigned)st.wMinute,(unsigned)st.wSecond,(unsigned)st.wMilliseconds);char *ename=json_escape(experiment);if(!ename)goto done;size_t bodycap=strlen(ename)+192;char *body=(char*)malloc(bodycap);if(!body){free(ename);goto done;}snprintf(body,bodycap,"{\"name\":\"%s\",\"createdAt\":\"%s\",\"colors\":[\"#5B8FF9\",\"#5B8FF9\"]}",ename,timestamp);free(ename);size_t pathcap=strlen(workspace)+strlen(project)+48;path=(char*)malloc(pathcap);if(!path){free(body);goto done;}snprintf(path,pathcap,"/api/project/%s/%s/experiment",workspace,project);if(!call_json(host,port,secure,L"POST",path,sid,body,&r)){free(body);set_error(error,error_capacity,"SwanLab experiment request failed");goto done;}free(body);if(!check_response(&r,error,error_capacity,"experiment creation"))goto done;if(!json_id_field((char*)r.data,"cuid",experiment_id,sizeof(experiment_id))){set_error(error,error_capacity,"SwanLab experiment response omitted its ID");goto done;}free(r.data);r.data=NULL;free(path);path=NULL;
    FILE *f=fopen(csv_path,"rb");if(!f){set_error(error,error_capacity,"cannot open scalar CSV file");goto done;}char line_buffer[4096];char *line=line_buffer;size_t metric_cap=4u*1024u*1024u,metric_used=0;char *metrics=(char*)malloc(metric_cap);char *series=(char*)calloc(metric_cap,1);char **keys=(char**)calloc(128,sizeof(char*));size_t key_count=0;if(!metrics||!series||!keys){free(metrics);free(series);free(keys);fclose(f);goto done;}metrics[0]=0;size_t series_used=0,uploaded=0;while(fgets(line,(int)sizeof(line_buffer),f)){char *p=line;while(isspace((unsigned char)*p))p++;if(!*p||*p=='#'||!strncmp(p,"step,",5))continue;char *comma1=strchr(p,',');if(!comma1)continue;*comma1++=0;char *comma2=strchr(comma1,',');if(!comma2)continue;*comma2++=0;char *end=NULL;errno=0;unsigned long long step=strtoull(p,&end,10);while(end&&isspace((unsigned char)*end))end++;if(errno||!end||*end)continue;while(*comma1&&isspace((unsigned char)comma1[strlen(comma1)-1]))comma1[strlen(comma1)-1]=0;if(!*comma1)continue;char *keyj=json_escape(comma1);if(!keyj){free(metrics);free(series);for(size_t i=0;i<key_count;i++)free(keys[i]);free(keys);fclose(f);goto done;}errno=0;double value=strtod(comma2,&end);while(end&&isspace((unsigned char)*end))end++;if(errno||!end||(*end&&*end!='\r'&&*end!='\n')||!isfinite(value)){free(keyj);continue;}char item[512];int n=snprintf(item,sizeof(item),"%s{\"key\":\"%s\",\"index\":%llu,\"data\":%.9g}",uploaded?",":"",keyj,step,value);if(n<0||(size_t)n>=sizeof(item)||metric_used+(size_t)n+2>=metric_cap){free(keyj);free(metrics);free(series);for(size_t i=0;i<key_count;i++)free(keys[i]);free(keys);fclose(f);set_error(error,error_capacity,"metric CSV too large for one batch");goto done;}memcpy(metrics+metric_used,item,(size_t)n+1);metric_used+=(size_t)n;int found=0;for(size_t i=0;i<key_count;i++)if(!strcmp(keys[i],comma1)){found=1;break;}if(!found){if(key_count==128){free(keyj);free(metrics);free(series);for(size_t i=0;i<key_count;i++)free(keys[i]);free(keys);fclose(f);set_error(error,error_capacity,"CSV has more than 128 distinct metric names");goto done;}size_t key_bytes=strlen(comma1)+1;keys[key_count]=(char*)malloc(key_bytes);if(keys[key_count])memcpy(keys[key_count],comma1,key_bytes);if(!keys[key_count]){free(keyj);free(metrics);free(series);for(size_t i=0;i<key_count;i++)free(keys[i]);free(keys);fclose(f);goto done;}char def[512];n=snprintf(def,sizeof(def),"%s{\"key\":\"%s\",\"type\":\"SCALAR\"}",key_count?",":"",keyj);if(n<0||(size_t)n>=sizeof(def)||series_used+(size_t)n+2>=metric_cap){free(keyj);free(metrics);free(series);for(size_t i=0;i<=key_count;i++)free(keys[i]);free(keys);fclose(f);set_error(error,error_capacity,"metric series schema is too large");goto done;}memcpy(series+series_used,def,(size_t)n+1);series_used+=(size_t)n;key_count++;}free(keyj);uploaded++;}fclose(f);if(!uploaded){free(metrics);free(series);free(keys);set_error(error,error_capacity,"CSV contains no valid step,key,value scalar rows");goto done;}
    size_t seriescap=series_used+32;body=(char*)malloc(seriescap);if(!body){free(metrics);free(series);for(size_t i=0;i<key_count;i++)free(keys[i]);free(keys);goto done;}snprintf(body,seriescap,"{\"series\":[%s]}",series);free(series);pathcap=strlen(workspace)+strlen(project)+48;free(path);path=(char*)malloc(pathcap);if(!path){free(body);free(metrics);for(size_t i=0;i<key_count;i++)free(keys[i]);free(keys);goto done;}snprintf(path,pathcap,"/api/projects/%s/%s/series",workspace,project);if(!call_json(host,port,secure,L"POST",path,sid,body,&r)){free(body);free(metrics);for(size_t i=0;i<key_count;i++)free(keys[i]);free(keys);set_error(error,error_capacity,"SwanLab series definition failed");goto done;}free(body);if(!check_response(&r,error,error_capacity,"series definition")){free(metrics);for(size_t i=0;i<key_count;i++)free(keys[i]);free(keys);goto done;}free(r.data);r.data=NULL;for(size_t i=0;i<key_count;i++)free(keys[i]);free(keys);
    /* Current SwanLab SDK HTTP transport accepts scalar batches at /house/metrics. */
    size_t paycap=strlen(project_id)+strlen(experiment_id)+metric_used+128;body=(char*)malloc(paycap);if(!body){free(metrics);goto done;}snprintf(body,paycap,"{\"type\":\"scalar\",\"projectId\":\"%s\",\"experimentId\":\"%s\",\"metrics\":[%s]}",project_id,experiment_id,metrics);free(metrics);if(!call_json(host,port,secure,L"POST","/api/house/metrics",sid,body,&r)){free(body);set_error(error,error_capacity,"SwanLab scalar upload failed");goto done;}free(body);if(!check_response(&r,error,error_capacity,"scalar upload"))goto done;free(r.data);r.data=NULL;
    GetSystemTime(&st);snprintf(timestamp,sizeof(timestamp),"%04u-%02u-%02uT%02u:%02u:%02u.%03uZ",(unsigned)st.wYear,(unsigned)st.wMonth,(unsigned)st.wDay,(unsigned)st.wHour,(unsigned)st.wMinute,(unsigned)st.wSecond,(unsigned)st.wMilliseconds);bodycap=strlen(timestamp)+64;body=(char*)malloc(bodycap);if(!body)goto done;snprintf(body,bodycap,"{\"state\":\"FINISHED\",\"finishedAt\":\"%s\",\"from\":\"sdk\"}",timestamp);pathcap=strlen(workspace)+strlen(project)+strlen(experiment_id)+80;free(path);path=(char*)malloc(pathcap);if(!path){free(body);goto done;}snprintf(path,pathcap,"/api/project/%s/%s/runs/%s/state",workspace,project,experiment_id);if(!call_json(host,port,secure,L"PUT",path,sid,body,&r)){free(body);set_error(error,error_capacity,"SwanLab finish request failed");goto done;}free(body);if(!check_response(&r,error,error_capacity,"finish"))goto done;free(r.data);r.data=NULL;ok=1;set_error(error,error_capacity,"");
done:free(path);free(r.data);if(ok)printf("swanlab_uploaded=%zu workspace=%s project=%s experiment_id=%s\n",uploaded,workspace,project,experiment_id);return ok;
}
#else
int ama10_swanlab_upload_csv(const char *base_url,const char *workspace,const char *project,const char *experiment,const char *csv_path,char *error,size_t error_capacity){(void)base_url;(void)workspace;(void)project;(void)experiment;(void)csv_path;set_error(error,error_capacity,"SwanLab HTTPS transport currently requires Windows WinHTTP");return 0;}
#endif
